templates.common/home:
{# Reamur Reference — tema de referencia. Sem scripts, eventos, filtros inseguros ou autoescape. #}
{{ header }}
<main class="ref-main">
  <div class="ref-container">
    <header class="ref-page-head">
      <p class="ref-kicker">{{ text_kicker|default('Reamur Reference') }}</p>
      <h1 class="ref-title">{{ heading_title|default('Bem-vindo') }}</h1>
      <p class="ref-lead">{{ text_tagline|default('Um tema completo, seguro e pronto para servir de base.') }}</p>
    </header>
    {% include 'partial/theme-scene-block.twig' %}
    {% if theme_scene.enabled|default(false) and theme_scene.slot|default('') == 'home_top' %}{% include 'partial/theme-scene.twig' %}{% endif %}
    {% for section in cms_home_sections|default([]) %}
      {% if section == 'hero' %}{% include 'partial/hero.twig' %}
      {% elseif section == 'about' %}{% include 'partial/about.twig' %}
      {% elseif section == 'methodology' %}{% include 'partial/methodology.twig' %}
      {% elseif section == 'skills' %}{% include 'partial/skills.twig' %}
      {% elseif section == 'services' %}{% include 'partial/services.twig' %}
      {% elseif section == 'testimonials' %}{% include 'partial/testimonials.twig' %}
      {% elseif section == 'portfolio' %}{% include 'partial/portfolio.twig' %}
      {% elseif section == 'tools' %}{% include 'partial/tools.twig' %}
      {% elseif section == 'news' %}{% include 'partial/news.twig' %}
      {% elseif section == 'clients' %}{% include 'partial/clients.twig' %}
      {% elseif section == 'contact' %}{% include 'partial/contact.twig' %}
      {% endif %}
    {% endfor %}
  </div>
</main>

templates.partial/services:
{# Reamur Reference / services — grade de servicos #}
<section class="ref-section ref-section--services">
  <div class="ref-container">
<h2 class="ref-h2">{{ text_services_title|default('Servicos') }}</h2>
    {% if services %}<div class="ref-grid">
      {% for item in services %}<article class="ref-card">
        {% if item.image|default('') %}<img class="ref-card-img" src="{{ item.image }}" alt="{{ item.title|default(item.name|default('')) }}" loading="lazy">{% endif %}
        <h3 class="ref-card-title">{{ item.title|default(item.name|default('')) }}</h3>
        <p class="ref-card-text">{{ item.description|default(item.summary|default('')) }}</p>
        {% if item.href|default('') %}<a class="ref-btn" href="{{ item.href }}">{{ text_read_more|default('Ver mais') }}</a>{% endif %}
      </article>{% endfor %}
    </div>{% else %}<p class="ref-empty">Nenhum servico publicado.</p>{% endif %}
  </div>
</section>

